    '''
    Returns an Interaction score for the given `user` and `source`
    '''
    score = 0
    if source.date_added > user.date_added:
        score += 1
    if source.user == user:
        score += 1
    if source.roman != source.pinyin and source.pinyin:
        score += 1
    if source.ch != source.gloss:
        score += 1
    if source.part_of_speech:
        score += 1
    if source.records():
        score += source.records.count()
    if source.comments():
        score += source.comments.count()
    return score

