def combination(val1, ops):
    valid = {'+': lambda x: x, '-': lambda x: -x, '!': lambda x: not x}
    constant = 0
    for op in ops:
        if op in valid:
            # valid operator
            constant += valid[op](constant)
        else:
            # valid number
            constant += float(op)
    result = constant
    if isinstance(val1, bool):
        result = bool(constant)
    return result

